                HighwayReference.multiplyPairwiseAddingWhereBF16ToF32(mask.raw, a.raw, b.raw),
                "mask: \(describe(mask)), a: \(describe(a)), b: \(describe(b))"
            )
        }
        mismatches.record()
    }
}
